    if (!discountResult.ok) return discountResult;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountResult.value > 0) {
      newLine.discountPercent = discountResult.value;
    }
    enrichedLines.push(newLine);
