test('createInvoice accepts EOM (end of month) terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
